//! SD-36 consolidation, corpus-bundle correctness follow-up (post Epic A;
//! `decisions.md` §8): the sanitised corpus bundle
//! (`apps/desktop/src-tauri/resources/corpus_bundle/`, generated by
//! `scripts/gen-corpus-bundle.mjs` from `data/corpus/`, mapped onto
//! `data/corpus/` inside the packaged app by `tauri.conf.json`'s
//! `bundle.resources`) must be a REAL build product with no lost content --
//! presence on disk is not the proof; the same live loaders reading the same
//! population out of it is.
//!
//! This test (a) regenerates the bundle by actually running the tracked
//! generator (so a stale, hand-edited, or partially-regenerated bundle
//! cannot pass), then (b) points the SAME production loaders
//! (`rules_core::corpus_loader::{load_equipment_corpus, load_spell_corpus}`,
//! `rules_core::race_resolver::load_race_corpus`) at the bundle and at the
//! raw, git-tracked `data/corpus/` in turn, and asserts parity per book:
//!
//! * the same race roster ids (`RaceCorpus::race_keys()`)
//! * the same equipment record count
//! * the same spell record count
//! * zero loader diagnostics on EITHER side (a diagnostic on the raw side
//!   would mean the ground truth itself is broken; one on the bundle side
//!   only would mean the sanitiser broke something the raw corpus did not
//!   have wrong -- `race_resolver::RaceCorpus`'s loader calls
//!   `validate_license` on every record it reads, so a license/PI field the
//!   bundle generator dropped or corrupted surfaces here as a diagnostic or
//!   as a missing race, not silently)
//!
//! Every assertion names the first differing book/record so a real
//! regression is diagnosable from the failure message alone, per
//! `AGENTS.md`'s "no fake completion" rule -- this is a correctness gate, not
//! a presence check.
//!
//! Scope: only books that carry at least one of the six kind directories the
//! generator mirrors (`_settled`, `equipment`, `spell`, `trait_generic`,
//! `race`, `race_trait`) are compared. A handful of onboarded books (e.g.
//! `bonus_bestiary`, `core_essentials`, `inner_sea_bestiary`,
//! `inner_sea_taverns`) carry none of the six today and are legitimately
//! absent from the bundle entirely -- including them here would compare a
//! "book directory not found" diagnostic against a raw side that has a real
//! directory with irrelevant content, which is a directory-existence
//! artifact, not a corpus-fidelity defect.

use codex::rules_core::corpus_loader::{load_equipment_corpus, load_spell_corpus, BookCorpusRoot};
use codex::rules_core::race_resolver::load_race_corpus;
use std::path::{Path, PathBuf};
use std::process::Command;

const RELEVANT_KIND_DIRS: &[&str] = &["_settled", "equipment", "spell", "trait_generic", "race", "race_trait"];

/// `apps/desktop/src-tauri`'s own repo root, by the same
/// `CARGO_MANIFEST_DIR`-walk `authoring_workbench::codex_repo_root`'s
/// compile-time fallback uses.
fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent() // apps/desktop
        .and_then(Path::parent) // apps
        .and_then(Path::parent) // repo root
        .expect("CARGO_MANIFEST_DIR should be <repo root>/apps/desktop/src-tauri")
        .to_path_buf()
}

/// Actually runs the tracked generator so this test proves the CURRENT
/// generator source produces a bundle that round-trips, not whatever
/// happened to be on disk already (a stale or hand-edited bundle must not be
/// able to pass this gate).
fn regenerate_bundle(repo_root: &Path) {
    let script = repo_root.join("scripts/gen-corpus-bundle.mjs");
    assert!(script.is_file(), "generator script missing at {}", script.display());
    let output = Command::new("node")
        .arg(&script)
        .current_dir(repo_root)
        .output()
        .unwrap_or_else(|e| panic!("failed to run `node {}`: {e} (Node.js must be on PATH)", script.display()));
    assert!(
        output.status.success(),
        "gen-corpus-bundle.mjs exited with {}\nstdout: {}\nstderr: {}",
        output.status,
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
}

fn books_with_relevant_kind(raw_root: &Path) -> Vec<String> {
    let mut books: Vec<String> = std::fs::read_dir(raw_root)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", raw_root.display()))
        .filter_map(|entry| entry.ok())
        .filter(|entry| entry.path().is_dir())
        .filter(|entry| RELEVANT_KIND_DIRS.iter().any(|kind| entry.path().join(kind).is_dir()))
        .map(|entry| entry.file_name().to_string_lossy().into_owned())
        .collect();
    books.sort();
    books
}

fn count_files(dir: &Path) -> usize {
    let mut count = 0;
    let mut stack = vec![dir.to_path_buf()];
    while let Some(current) = stack.pop() {
        let Ok(entries) = std::fs::read_dir(&current) else { continue };
        for entry in entries.filter_map(|e| e.ok()) {
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
            } else {
                count += 1;
            }
        }
    }
    count
}

#[test]
fn sanitised_corpus_bundle_has_the_same_race_equipment_and_spell_population_as_the_raw_corpus() {
    let repo_root = repo_root();
    let raw_root = repo_root.join("data/corpus");
    let bundle_root = repo_root.join("apps/desktop/src-tauri/resources/corpus_bundle");
    assert!(raw_root.is_dir(), "raw corpus root missing at {}", raw_root.display());

    regenerate_bundle(&repo_root);

    assert!(
        bundle_root.is_dir(),
        "generator did not produce a bundle directory at {}",
        bundle_root.display()
    );
    let bundle_file_count = count_files(&bundle_root);
    assert!(
        bundle_file_count > 1,
        "generated corpus bundle is empty (only found {bundle_file_count} file(s), expected the \
         .gitkeep plus thousands of sanitised corpus records) at {}",
        bundle_root.display()
    );

    let books = books_with_relevant_kind(&raw_root);
    assert!(
        !books.is_empty(),
        "expected at least one book with race/equipment/spell/trait_generic content under {}",
        raw_root.display()
    );

    let mut race_mismatches: Vec<String> = Vec::new();
    let mut equipment_mismatches: Vec<String> = Vec::new();
    let mut spell_mismatches: Vec<String> = Vec::new();

    for book in &books {
        let raw_dir = raw_root.join(book);
        let bundle_dir = bundle_root.join(book);

        // -- equipment --------------------------------------------------
        let raw_eq = load_equipment_corpus(&[BookCorpusRoot { book_id: book, dir: &raw_dir }]);
        let bundle_eq = load_equipment_corpus(&[BookCorpusRoot { book_id: book, dir: &bundle_dir }]);
        if !raw_eq.diagnostics.is_empty() {
            equipment_mismatches.push(format!(
                "{book}: raw equipment load produced {} diagnostic(s) (ground truth is broken): {:?}",
                raw_eq.diagnostics.len(),
                raw_eq.diagnostics
            ));
        }
        if !bundle_eq.diagnostics.is_empty() {
            equipment_mismatches.push(format!(
                "{book}: bundle equipment load produced {} diagnostic(s): {:?}",
                bundle_eq.diagnostics.len(),
                bundle_eq.diagnostics
            ));
        }
        if raw_eq.records.len() != bundle_eq.records.len() {
            equipment_mismatches.push(format!(
                "{book}: equipment record count differs -- raw={} bundle={}",
                raw_eq.records.len(),
                bundle_eq.records.len()
            ));
        }

        // -- spell --------------------------------------------------------
        let raw_sp = load_spell_corpus(&[BookCorpusRoot { book_id: book, dir: &raw_dir }]);
        let bundle_sp = load_spell_corpus(&[BookCorpusRoot { book_id: book, dir: &bundle_dir }]);
        if !raw_sp.diagnostics.is_empty() {
            spell_mismatches.push(format!(
                "{book}: raw spell load produced {} diagnostic(s) (ground truth is broken): {:?}",
                raw_sp.diagnostics.len(),
                raw_sp.diagnostics
            ));
        }
        if !bundle_sp.diagnostics.is_empty() {
            spell_mismatches.push(format!(
                "{book}: bundle spell load produced {} diagnostic(s): {:?}",
                bundle_sp.diagnostics.len(),
                bundle_sp.diagnostics
            ));
        }
        if raw_sp.records.len() != bundle_sp.records.len() {
            spell_mismatches.push(format!(
                "{book}: spell record count differs -- raw={} bundle={}",
                raw_sp.records.len(),
                bundle_sp.records.len()
            ));
        }

        // -- race (also proves license/PI validation survives the bundle) -
        let raw_race = load_race_corpus(&[BookCorpusRoot { book_id: book, dir: &raw_dir }]);
        let bundle_race = load_race_corpus(&[BookCorpusRoot { book_id: book, dir: &bundle_dir }]);
        if !raw_race.diagnostics().is_empty() {
            race_mismatches.push(format!(
                "{book}: raw race load produced {} diagnostic(s) (ground truth is broken): {:?}",
                raw_race.diagnostics().len(),
                raw_race.diagnostics()
            ));
        }
        if !bundle_race.diagnostics().is_empty() {
            race_mismatches.push(format!(
                "{book}: bundle race load produced {} diagnostic(s) (license/PI validation or a \
                 dropped field likely broke a record): {:?}",
                bundle_race.diagnostics().len(),
                bundle_race.diagnostics()
            ));
        }
        let mut raw_keys: Vec<&str> = raw_race.race_keys();
        let mut bundle_keys: Vec<&str> = bundle_race.race_keys();
        raw_keys.sort_unstable();
        bundle_keys.sort_unstable();
        if raw_keys != bundle_keys {
            let only_raw: Vec<&&str> = raw_keys.iter().filter(|k| !bundle_keys.contains(k)).collect();
            let only_bundle: Vec<&&str> = bundle_keys.iter().filter(|k| !raw_keys.contains(k)).collect();
            race_mismatches.push(format!(
                "{book}: race roster differs -- raw has {} race(s), bundle has {} race(s); \
                 only in raw: {only_raw:?}; only in bundle: {only_bundle:?}",
                raw_keys.len(),
                bundle_keys.len()
            ));
        }
    }

    assert!(
        equipment_mismatches.is_empty(),
        "{} book(s) with an equipment parity defect between data/corpus/ and the sanitised \
         bundle:\n{}",
        equipment_mismatches.len(),
        equipment_mismatches.join("\n")
    );
    assert!(
        spell_mismatches.is_empty(),
        "{} book(s) with a spell parity defect between data/corpus/ and the sanitised bundle:\n{}",
        spell_mismatches.len(),
        spell_mismatches.join("\n")
    );
    assert!(
        race_mismatches.is_empty(),
        "{} book(s) with a race parity defect between data/corpus/ and the sanitised bundle:\n{}",
        race_mismatches.len(),
        race_mismatches.join("\n")
    );
}
